    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(false);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_2, "open")).toBe(false);
    expect(await ui.claimAction(pg_uma, c_ada_3, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_4, "open")).toBe(false);
    expect(await ui.bulkOpen(pg_uma, [c_ada_0, c_ada_4])).toEqual({ opened: 0, refused: 2 });
    expect(await ui.editClaim(pg_uma, c_ada_0, {"note": "x"})).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("6.00");
